LOGIN_HTML = """<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>设备接入采集盒配置系统</title>
  <style>
    :root{--primary:#0797dc;--primary-dark:#087fbd;--text:#26384a;--muted:#7c8a99;--line:#dbe3ea;--bg:#f2f5f8}
    *{box-sizing:border-box}body{margin:0;min-height:100vh;background:var(--bg);color:var(--text);font:14px/1.5 "Microsoft YaHei",Arial,sans-serif}.login-head{height:68px;background:var(--primary);color:#fff;display:flex;align-items:center;padding:0 34px}.login-brand{display:flex;align-items:center;gap:14px}.login-mark{width:38px;height:38px;border:3px solid #fff;border-radius:5px;display:grid;place-items:center;font-size:13px;font-weight:800}.login-brand strong{font-size:18px}.login-brand span{display:block;font-size:11px;opacity:.8}.login-shell{min-height:calc(100vh - 68px);display:grid;place-items:center;padding:28px}main{width:min(420px,100%);background:#fff;border:1px solid var(--line);border-radius:5px;padding:34px 38px;box-shadow:0 8px 24px rgba(31,65,92,.08)}h1{font-size:22px;margin:0 0 6px}p{margin:0 0 24px;color:var(--muted)}label{display:block;font-weight:600;margin:14px 0 6px}input{width:100%;height:42px;border:1px solid #cbd5df;border-radius:3px;padding:0 12px;font:inherit}input:focus{outline:2px solid rgba(7,151,220,.18);border-color:var(--primary)}button{width:100%;height:42px;margin-top:22px;border:0;border-radius:3px;background:var(--primary);color:#fff;font:inherit;font-weight:700;cursor:pointer}button:hover{background:var(--primary-dark)}.error{min-height:21px;margin:12px 0 0;color:#d92d20}
  </style>
</head>
<body><header class="login-head"><div class="login-brand"><div class="login-mark">J+</div><div><strong>聚垒科技</strong><span>jvlei.com</span></div></div></header><div class="login-shell"><main><h1>设备接入采集盒配置系统</h1><p>登录 K2B 报告上传网关</p><form id="login"><label for="username">用户名</label><input id="username" value="admin" autocomplete="username"><label for="password">密码</label><input id="password" type="password" autocomplete="current-password"><button type="submit">登录</button><div class="error" id="error"></div></form></main></div>
<script>
document.getElementById('login').onsubmit=async(event)=>{event.preventDefault();const response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})});const data=await response.json();if(data.ok){location.href='/';return}error.textContent=data.error||'登录失败'};
</script></body></html>"""


